<?php
require_once __DIR__.'/AnalysisNormalizer.php';require_once __DIR__.'/OpenRouterAnalyzer.php';
final class GeminiCallAnalyzer {
 public function __construct(private string $baseUrl,private string $apiKey,private string $model,private int $timeout=120){}
 public function analyze(string $path,string $mime,array $call):array{$bytes=file_get_contents($path);if(!is_string($bytes)||$bytes==='')throw new RuntimeException('AUDIO_UNAVAILABLE');$payload=['model'=>$this->model,'input'=>[['type'=>'text','text'=>OpenRouterAnalyzer::prompt($call)],['type'=>'audio','data'=>base64_encode($bytes),'mime_type'=>$mime]],'response_format'=>['type'=>'text','mime_type'=>'application/json','schema'=>OpenRouterAnalyzer::schema()],'store'=>false];$ch=curl_init(rtrim($this->baseUrl,'/').'/interactions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>$this->timeout,CURLOPT_HTTPHEADER=>['Content-Type: application/json','x-goog-api-key: '.$this->apiKey,'Api-Revision: 2026-05-20'],CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);if(!is_string($raw)||$code<200||$code>=300)throw new RuntimeException('GEMINI_REQUEST_FAILED');$data=json_decode($raw,true,512,JSON_THROW_ON_ERROR);$text='';foreach(($data['steps']??[])as $step)if(($step['type']??'')==='model_output')foreach(($step['content']??[])as $item)if(($item['type']??'')==='text')$text=(string)($item['text']??'');$analysis=json_decode($text,true,512,JSON_THROW_ON_ERROR);if(!is_array($analysis))throw new RuntimeException('GEMINI_INVALID_RESPONSE');return(new AnalysisNormalizer())->normalize($analysis,'gemini',$this->model);}
}
